module util {
  function money_round(amount: decimal) -> decimal
    using (round(amount, 2));

  function money_round(amount: decimal, places: int64) -> decimal
    using (round(amount, places));

  function total_of(variadic amounts: decimal) -> decimal
    using (round(sum(array_unpack(amounts)), 2));

  function apply_discount(amount: decimal, pct: decimal, floor_amount: optional decimal) -> decimal
    using (
      with
        d := round(amount * (1.0n - pct / 100.0n), 2)
      select
        if exists floor_amount then
          (if d > floor_amount then d else floor_amount)
        else
          d
    );

  function gross_with_tax(net: decimal, named only tax_pct: decimal = 0) -> decimal
    using (round(net * (1.0n + tax_pct / 100.0n), 2));

  function installments(total: decimal, count: int64) -> set of decimal
    using (
      if count < 1 then
        <decimal>{}
      else
        (
          with
            each_installment := round(total / (if count < 1 then 1 else count), 2),
            i := range_unpack(range(1, if count < 1 then 1 else count + 1))
          select
            if i < count then
              each_installment
            else
              total - (count - 1) * each_installment
        )
    );
}

module util {
  function money_round(amount: decimal) -> decimal
    using (round(amount, 2));

  function money_round(amount: decimal, places: int64) -> decimal
    using (round(amount, places));

  function total_of(variadic amounts: decimal) -> decimal
    using (round(sum(array_unpack(amounts)), 2));

  function apply_discount(amount: decimal, pct: decimal, floor_amount: optional decimal) -> decimal
    using (
      with
        d := round(amount * (1.0n - pct / 100.0n), 2)
      select
        if exists floor_amount then
          (if d > assert_exists(floor_amount) then d else assert_exists(floor_amount))
        else
          d
    );

  function gross_with_tax(net: decimal, named only tax_pct: decimal = 0) -> decimal
    using (round(net * (1.0n + tax_pct / 100.0n), 2));

  function installments(total: decimal, count: int64) -> set of decimal
    using (
      if count < 1 then
        <decimal>{}
      else
        (
          with
            each_installment := round(total / (if count < 1 then 1 else count), 2),
            i := range_unpack(range(1, if count < 1 then 1 else count + 1))
          select
            if i < count then
              each_installment
            else
              total - (count - 1) * each_installment
        )
    );
}

module billing {
  type Customer {
    required name: str {
      constraint exclusive;
    }
    required discount_pct: decimal {
      default := 0n;
    }
  }

  type LineItem {
    required invoice: Invoice;
    required description: str;
    required qty: int64;
    required unit_price: decimal {
      constraint expression on (self = util::money_round(self));
    }
    required line_total := util::money_round(<decimal>.qty * .unit_price);
  }

  type Invoice {
    required code: str {
      constraint exclusive;
    }
    required customer: Customer;
    required paid: bool {
      default := false;
    }
    minimum_charge: decimal;
    required installment_count: int64 {
      default := 1;
    }

    multi lines := .<invoice[is LineItem];

    required subtotal := util::money_round(sum(.lines.line_total));

    required total_due := util::apply_discount(.subtotal, .customer.discount_pct, .minimum_charge);
  }

  function customer_outstanding(customer_name: str) -> decimal {
    using (
      util::money_round(
        sum(
          (
            select Invoice
            filter .customer.name = customer_name and not .paid
          ).total_due
        )
      )
    );
    volatility := 'Stable';
  }
}

